import serial
import time

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600


def open_serial_port(port_name, baud_value):
    """Open and configure a serial port for data exchange."""
    # Configure a serial port with a timeout to avoid blocking reads
    return serial.Serial(port_name, baud_value, timeout=1)


def read_one_reading(serial_port):
    """Read and decode one line of data from the serial port."""
    # Wait for a line and decode it into a human readable string
