    # Configure a serial port with a timeout to avoid blocking reads
    return serial.Serial(port, baud, timeout=1)


def read_one_line(serial_port):
    """Read a single line of text from the serial data stream."""
    # Collect bytes until a newline marks the end of a message
    line_bytes = b""
    while True:
        next_byte = serial_port.read(1)
        if not next_byte:
            break
        line_bytes += next_byte
        if b"\n" in line_bytes:
            break
    return line_bytes.decode("utf-8", "ignore").strip()


if __name__ == "__main__":
