                print("Received:", received_line)
            time.sleep(0.05)
    except serial.SerialException as serial_error:
        # Report a missing or unresponsive device
        print("Serial error:", serial_error)
    except KeyboardInterrupt:
        # Allow the operator to stop the exchange cleanly
        print("Exchange stopped")
