# Motor controller driver for a Raspberry Pi using gpiozero
# Drives a PWM output on a GPIO pin and reports the applied state
from gpiozero import PWMOutputDevice
import time
import sys

# Pin assignments for the motor controller (BCM numbering)
MOTOR_PINS = {
    "forward": 5,
    "reverse": 6,
    "left": 13,
    "right": 17,
    "idle": 18,
    "busy": 22,
    "error": 23,
    "ready": 24,
    "start": 27,
}


def create_motor_device(pin_number):
    """Create and return a PWMOutputDevice for the given pin."""
    try:
        device = PWMOutputDevice(pin_number, active_high=True, initial_value=0)
        return device
    except Exception as e:
        print(f"Error creating motor device on pin {pin_number}: {e}")
        sys.exit(1)


def apply_motor_state(devices, state):
    """Apply a motor state to the corresponding gpiozero devices."""
    for pin_name, pin_number in MOTOR_PINS.items():
        if state.get(pin_name):
            devices[pin_name].value = 1
        else:
            devices[pin_name].value = 0


def report_state(devices):
    """Report the current state of each motor control pin."""
    for pin_name, pin_number in MOTOR_PINS.items():
        print(f"{pin_name} (pin {pin_number}): {int(devices[pin_name].value)}")


def main():
    """Main function to continuously report motor control states."""
    devices = {
        name: create_motor_device(number)
        for name, number in MOTOR_PINS.items()
    }

    try:
        while True:
            # Example state - replace with your actual logic
            current_state = {"forward": True, "idle": True, "start": True}
            apply_motor_state(devices, current_state)
            report_state(devices)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        # Ensure all gpiozero devices are released
        for device in devices.values():
            device.close()


if __name__ == "__main__":
    main()
